func ntSel(c int32, a int32, b int32) int32 {
	// c ? a : b.
	if c != 0 {
		return a
	}
	return b
}

func ntFill(b *port.Bitmap, st *port.Cells) int32 {
	// Every byte pseudo-random, from a seeded generator.
	var x int32 = 0
	var y int32 = 0
	var c int32 = 0
	for y < port.BitmapH(b) {
		x = 0
		for x < port.BitmapW(b) {
			c = 0
			for c < port.BitmapChannels(b) {
				port.BitmapSetU8(b, x, y, c, splitmix.SmBelow(st, 256))
				c += 1
			}
			x += 1
		}
		y += 1
	}
	return 0
}

func ntSame(a *port.Bitmap, b *port.Bitmap) int32 {
	// 1 when the two have one shape and one set of bytes.
	var x int32 = 0
	var y int32 = 0
	var c int32 = 0
	var same int32 = 1
	if port.BitmapW(a) != port.BitmapW(b) {
		return 0
	}
	if port.BitmapH(a) != port.BitmapH(b) {
		return 0
	}
	if port.BitmapChannels(a) != port.BitmapChannels(b) {
		return 0
	}
	for y < port.BitmapH(a) {
		x = 0
		for x < port.BitmapW(a) {
			c = 0
			for c < port.BitmapChannels(a) {
				if port.BitmapU8(a, x, y, c) != port.BitmapU8(b, x, y, c) {
					same = 0
				}
				c += 1
			}
			x += 1
		}
		y += 1
	}
	return same
}

func ntRect(b *port.Bitmap, x0 int32, y0 int32, x1 int32, y1 int32, r int32, g int32, bl int32) int32 {
	// Fill [x0,x1) x [y0,y1) with a colour (a 1-channel bitmap takes r).
	var x int32 = 0
	var y int32 = y0
	for y < y1 {
		x = x0
		for x < x1 {
			port.BitmapSetU8(b, x, y, 0, r)
			if port.BitmapChannels(b) == 3 {
				port.BitmapSetU8(b, x, y, 1, g)
				port.BitmapSetU8(b, x, y, 2, bl)
			}
			x += 1
		}
		y += 1
	}
	return 0
}

func ntCount(m *port.Bitmap) int32 {
	// Nonzero pixels of channel 0.
	var x int32 = 0
	var y int32 = 0
	var n int32 = 0
	for y < port.BitmapH(m) {
		x = 0
		for x < port.BitmapW(m) {
			if port.BitmapU8(m, x, y, 0) != 0 {
				n += 1
			}
			x += 1
		}
		y += 1
	}
	return n
}

func ntLutFill(lut *port.Cells, st *port.Cells, n int32) int32 {
	// n random cells (high bits set too, so only the low 8 may reach the mask).
	var i int32 = 0
	for i < n {
		port.CellsPush(lut, (splitmix.SmBelow(st, 65536)*4096)+splitmix.SmBelow(st, 4096))
		i += 1
	}
	return 0
}

