func TestHashOfKnownBitmapsIsFnv1a64(emonT *testing.T) {
	// Values computed independently in babashka: FNV-1a 64 over w, h, channels (4 bytes LE each), then the bytes.
	var a *port.Bitmap = port.BitmapNew(1, 1, 1)
	var b *port.Bitmap = port.BitmapNew(2, 1, 1)
	var c *port.Bitmap = port.BitmapNew(2, 2, 3)
	var o *port.Cells = port.NewCells()
	var i int32 = 0
	port.CellsGrow(o, 2, 0)
	port.BitmapHash(a, o, 0)
	port.AssertEq(emonT, port.CellsAt(o, 0), 1935683416, "1x1 gray 0, high")
	port.AssertEq(emonT, port.CellsAt(o, 1), 767303708, "low")
	port.BitmapSetU8(b, 0, 0, 0, 7)
	port.BitmapSetU8(b, 1, 0, 0, 200)
	port.BitmapHash(b, o, 0)
	port.AssertEq(emonT, port.CellsAt(o, 0), 1420858788, "2x1 gray 7 200, high")
	port.AssertEq(emonT, port.CellsAt(o, 1), 367332152, "low")
	for i < 12 {
		port.BitmapSetU8(c, (i/3)%2, i/6, i%3, i+1)
		i += 1
	}
	port.BitmapHash(c, o, 0)
	port.AssertEq(emonT, port.CellsAt(o, 0), 2088399466, "2x2 rgb 1..12, high")
	port.AssertEq(emonT, port.CellsAt(o, 1), -379269774, "low")
	port.AssertEq64(emonT, norm.NmRefHash64(c), 8969607411369561458, "the reference's 64 bits")
}

