func TestQuarterTurnsAreClockwiseAndFourMakeNone(emonT *testing.T) {
	// A 3x2 picture, left to right and top to bottom 1..6; one clockwise turn makes a 2x3 picture whose rows are
	// [4 1], [5 2], [6 3].
	var s *port.Bitmap = port.BitmapNew(3, 2, 1)
	var q *port.Bitmap = port.BitmapNew(2, 3, 1)
	var h *port.Bitmap = port.BitmapNew(3, 2, 1)
	var w *port.Bitmap = port.BitmapNew(2, 3, 1)
	var z *port.Bitmap = port.BitmapNew(3, 2, 1)
	port.BitmapSetU8(s, 0, 0, 0, 1)
	port.BitmapSetU8(s, 1, 0, 0, 2)
	port.BitmapSetU8(s, 2, 0, 0, 3)
	port.BitmapSetU8(s, 0, 1, 0, 4)
	port.BitmapSetU8(s, 1, 1, 0, 5)
	port.BitmapSetU8(s, 2, 1, 0, 6)
	port.BitmapQuarterInto(s, q, 1)
	port.AssertEq(emonT, port.BitmapU8(q, 0, 0, 0), 4, "row 0, col 0")
	port.AssertEq(emonT, port.BitmapU8(q, 1, 0, 0), 1, "row 0, col 1")
	port.AssertEq(emonT, port.BitmapU8(q, 0, 1, 0), 5, "row 1, col 0")
	port.AssertEq(emonT, port.BitmapU8(q, 1, 1, 0), 2, "row 1, col 1")
	port.AssertEq(emonT, port.BitmapU8(q, 0, 2, 0), 6, "row 2, col 0")
	port.AssertEq(emonT, port.BitmapU8(q, 1, 2, 0), 3, "row 2, col 1")
	port.BitmapQuarterInto(s, h, 2)
	port.AssertEq(emonT, port.BitmapU8(h, 0, 0, 0), 6, "two turns: the last pixel comes first")
	port.AssertEq(emonT, port.BitmapU8(h, 2, 1, 0), 1, "and the first comes last")
	port.BitmapQuarterInto(s, w, 3)
	port.AssertEq(emonT, port.BitmapU8(w, 0, 0, 0), 3, "three turns: row 0, col 0 is the old top right")
	port.AssertEq(emonT, port.BitmapU8(w, 1, 2, 0), 4, "and the old bottom left is at the far corner")
	port.BitmapQuarterInto(s, q, 1)
	port.BitmapQuarterInto(q, z, 1)
	port.BitmapQuarterInto(z, q, 1)
	port.BitmapQuarterInto(q, h, 1)
	port.AssertEq(emonT, ntSame(s, h), 1, "four single turns are the identity")
}

func ntPage3(b *port.Bitmap) int32 {
	// Paper, a black block (600 px), a blue block (400 px), a light-grey block (800 px), and a column of 20 mid-grey
	// pixels beside the black block, an anti-aliased edge.
	ntRect(b, 0, 0, 100, 80, 255, 255, 255)
	ntRect(b, 10, 10, 40, 30, 0, 0, 0)
	ntRect(b, 60, 40, 80, 60, 31, 63, 159)
	ntRect(b, 10, 50, 50, 70, 207, 207, 207)
	ntRect(b, 40, 10, 41, 30, 102, 102, 102)
	return 0
}

func ntLayers(b *port.Bitmap, ws *port.Cells) int32 {
	var n int32 = norm.NmLayers(ws, norm.NmInkMerge(), norm.NmInkPaper(), norm.NmInkMin(), norm.NmInkSpike())
	norm.NmRoles(ws, norm.NmInkLight(), norm.NmInkChroma(), norm.NmInkBg())
	return n
}

func TestAPageOfThreeInksSeparatesIntoThreeLayersBySize(emonT *testing.T) {
	var b *port.Bitmap = port.BitmapNew(100, 80, 3)
	var ws *port.Cells = port.NewCells()
	ntPage3(b)
	norm.NmWsInit(ws)
	port.BitmapHistRgb(b, ws, norm.NmWsHist())
	port.AssertEq(emonT, ntLayers(b, ws), 3, "paper and three inks: three layers")
	port.AssertEq(emonT, norm.NmLayerCount(ws), 3, "the count is kept")
	port.AssertEq(emonT, norm.NmLayerGet(ws, 0, 0), 800, "layer 1 is the light grey block, the largest")
	port.AssertEq(emonT, norm.NmLayerGet(ws, 1, 0), 620, "layer 2 is black and holds its anti-aliased edge: 600 + 20")
	port.AssertEq(emonT, norm.NmLayerGet(ws, 2, 0), 400, "layer 3 is the blue block")
	port.AssertEq(emonT, norm.NmPaperGray(ws), 255, "the paper bin is white")
	port.AssertEq(emonT, norm.NmLayerGet(ws, 0, 8), evidence.IrLight(), "light grey: low chroma, lightness over ink-light")
	port.AssertEq(emonT, norm.NmLayerGet(ws, 1, 8), evidence.IrBody(), "black: the body")
	port.AssertEq(emonT, norm.NmLayerGet(ws, 2, 8), evidence.IrColor(), "blue: colour")
	port.AssertEq(emonT, norm.NmLayerGet(ws, 2, 4), 17, "blue's mean red is its bin centre, 1 * 17")
}

func TestLayerMasksAreOneLutPassAndHoldExactlyTheirInk(emonT *testing.T) {
	var b *port.Bitmap = port.BitmapNew(100, 80, 3)
	var m *port.Bitmap = port.BitmapNew(100, 80, 1)
	var lab *port.Bitmap = port.BitmapNew(100, 80, 1)
	var ws *port.Cells = port.NewCells()
	ntPage3(b)
	norm.NmWsInit(ws)
	port.BitmapHistRgb(b, ws, norm.NmWsHist())
	ntLayers(b, ws)
	norm.NmMaskInto(b, ws, 2, m)
	port.AssertEq(emonT, ntCount(m), 620, "the body mask: 600 + the edge column")
	port.AssertEq(emonT, port.BitmapU8(m, 10, 10, 0), 255, "inside the black block")
	port.AssertEq(emonT, port.BitmapU8(m, 40, 10, 0), 255, "on the anti-aliased column")
	port.AssertEq(emonT, port.BitmapU8(m, 9, 10, 0), 0, "outside")
	port.AssertEq(emonT, port.BitmapU8(m, 60, 40, 0), 0, "the blue block is not in it")
	norm.NmMaskInto(b, ws, 3, m)
	port.AssertEq(emonT, ntCount(m), 400, "the blue mask")
	port.AssertEq(emonT, port.BitmapU8(m, 79, 59, 0), 255, "its last pixel")
	norm.NmLabelInto(b, ws, lab)
	port.AssertEq(emonT, port.BitmapU8(lab, 0, 0, 0), 0, "paper is 0")
	port.AssertEq(emonT, port.BitmapU8(lab, 10, 50, 0), 1, "the grey block's id")
	port.AssertEq(emonT, port.BitmapU8(lab, 10, 10, 0), 2, "black's id")
	port.AssertEq(emonT, port.BitmapU8(lab, 60, 40, 0), 3, "blue's id")
}

