func rasSauvolaWhole(g *port.Bitmap, isum *port.Cells, isq *port.Cells, sq *port.Cells, m *port.Bitmap) int32 {
	raster.RasIntegral(g, isum, isq)
	return raster.RasSauvola(g, isum, isq, sq, m)
}

func ntSauvCase(g *port.Bitmap, sq *port.Cells) int32 {
	// 1 when the banded form (r = 15, k = 87) equals the whole-page ras-sauvola, mask and ink count.
	var a *port.Bitmap = port.BitmapNew(port.BitmapW(g), port.BitmapH(g), 1)
	var b *port.Bitmap = port.BitmapNew(port.BitmapW(g), port.BitmapH(g), 1)
	var isum *port.Cells = port.NewCells()
	var isq *port.Cells = port.NewCells()
	var sv *port.Cells = port.NewCells()
	var n1 int32 = rasSauvolaWhole(g, isum, isq, sq, a)
	var n2 int32 = norm.NmSauvola(g, b, 15, 87, sv)
	if n1 != n2 {
		return 0
	}
	return ntSame(a, b)
}

