func ntSauvBrute(g *port.Bitmap, m *port.Bitmap, r int32, k int32, sq *port.Cells) int32 {
	// Sauvola by the definition: every window summed directly (no integral image).
	var w int32 = port.BitmapW(g)
	var h int32 = port.BitmapH(g)
	var x int32 = 0
	var y int32 = 0
	var i int32 = 0
	var j int32 = 0
	var x0 int32 = 0
	var x1 int32 = 0
	var y0 int32 = 0
	var y1 int32 = 0
	var n int32 = 0
	var s int32 = 0
	var q int32 = 0
	var v int32 = 0
	var mean int32 = 0
	var vr int32 = 0
	var thr int32 = 0
	var ink int32 = 0
	for y < h {
		x = 0
		for x < w {
			x0 = x - r
			if x0 < 0 {
				x0 = 0
			}
			x1 = (x + r) + 1
			if x1 > w {
				x1 = w
			}
			y0 = y - r
			if y0 < 0 {
				y0 = 0
			}
			y1 = (y + r) + 1
			if y1 > h {
				y1 = h
			}
			s = 0
			q = 0
			j = y0
			for j < y1 {
				i = x0
				for i < x1 {
					v = port.BitmapU8(g, i, j, 0)
					s += v
					q += v * v
					i += 1
				}
				j += 1
			}
			n = (x1 - x0) * (y1 - y0)
			mean = s / n
			vr = (q / n) - (mean * mean)
			thr = mean + int32(((int64(mean)*int64(k))*int64((2*port.CellsAt(sq, vr))-256))/65536)
			if port.BitmapU8(g, x, y, 0) < thr {
				port.BitmapSetU8(m, x, y, 0, 255)
				ink += 1
			} else {
				port.BitmapSetU8(m, x, y, 0, 0)
			}
			x += 1
		}
		y += 1
	}
	return ink
}

