func ntTextLines(b *port.Bitmap, cdeg int32, ink int32) int32 {
	// Eight lines of ten two-part words (14 rows tall, a 4 px gap in each), the lines rising to the right by `cdeg`,
	// drawn in `ink` on a 1000 x 700 page.
	var co int32 = evidence.EvCos(cdeg)
	var si int32 = evidence.EvSin(cdeg)
	var li int32 = 0
	var wi int32 = 0
	var x int32 = 0
	var j int32 = 0
	var y int32 = 0
	var dy int32 = 0
	var on int32 = 0
	for li < 8 {
		wi = 0
		for wi < 10 {
			x = 0
			for x < 70 {
				on = 1
				if (x >= 32) && (x < 36) {
					on = 0
				}
				if on == 1 {
					dy = int32((int64((20+(wi*90))+x) * int64(si)) / int64(co))
					j = 0
					for j < 14 {
						y = ((60 + (li * 70)) - dy) + j
						if y >= 0 {
							if y < port.BitmapH(b) {
								ntRect(b, (20+(wi*90))+x, y, ((20+(wi*90))+x)+1, y+1, ink, ink, ink)
							}
						}
						j += 1
					}
				}
				x += 1
			}
			wi += 1
		}
		li += 1
	}
	return 0
}

func ntSkewOf(cdeg int32) int32 {
	var b *port.Bitmap = port.BitmapNew(1000, 700, 1)
	var pts *port.Cells = port.NewCells()
	var prof *port.Cells = port.NewCells()
	ntTextLines(b, cdeg, 255)
	return norm.NmDeskew(b, pts, prof)
}

func ntNear(got int32, want int32, tol int32) int32 {
	var d int32 = got - want
	if d < 0 {
		d = 0 - d
	}
	if d <= tol {
		return 1
	}
	return 0
}

