func ntInkFixture(bin *port.Bitmap, eng *port.Bitmap, body *port.Bitmap, gray *port.Bitmap) int32 {
	// Kin ink in columns 3..8 of rows 2..4 (18 px); the engine's in columns 6..11 (18 px, 9 shared); the body mask
	// over columns 3..5 only; gray 60 under the ink, 255 elsewhere.
	ntRect(gray, 0, 0, 20, 10, 255, 0, 0)
	ntRect(gray, 3, 2, 9, 5, 60, 0, 0)
	ntRect(bin, 3, 2, 9, 5, 255, 0, 0)
	ntRect(eng, 6, 2, 12, 5, 255, 0, 0)
	ntRect(body, 3, 2, 6, 5, 255, 0, 0)
	return 0
}

